set -euo pipefail
upload_dir=$(getent passwd "$SUDO_USER" | cut -d: -f6)
cd /opt/news-flow/current
/opt/news-flow/node/bin/node --input-type=module - <<'NODE'
import fs from 'node:fs';import {gunzipSync} from 'node:zlib';import {createRequire} from 'node:module';const root='/var/lib/news-flow/qc-public24-20261123',ch=createRequire('/opt/news-flow/current/package.json')('cheerio'),r=JSON.parse(fs.readFileSync(root+'/native-paths.json')),out=[];
for(const s of r.sites.filter(s=>['giacavattu.com.vn','gialaitv.vn','travelguide.org.vn','tintuctoday.net','danhgiaxe.com','dulichgiaitri.com'].includes(s.site))){const o={site:s.site,scriptContexts:s.scriptContexts,checks:[]};for(const p of s.checks.filter(p=>p.file&&!p.error)){const raw=gunzipSync(fs.readFileSync(p.file)).toString(),$=ch.load(raw),c={url:p.url,kind:p.kind,scripts:p.scripts,publicationHints:p.publicationHints};if(p.kind==='declared_script'){c.readScript=raw.slice(0,16000);}else if(p.kind==='exact_client_api'){try{const v=JSON.parse(raw);c.json=v;}catch{c.raw=raw.slice(0,400);}}else if(p.kind==='fresh_native_article'){c.meta=$('meta').toArray().map(e=>({name:$(e).attr('name')||$(e).attr('property')||$(e).attr('itemprop'),content:$(e).attr('content')})).filter(m=>/(date|time|publish|article|url)/i.test(m.name||''));c.times=$('time,[datetime],[itemprop*=date],[class*=date],[class*=time]').toArray().slice(0,20).map(e=>({tag:e.name,class:$(e).attr('class'),dt:$(e).attr('datetime'),text:$(e).text().replace(/\s+/g,' ').trim().slice(0,250)}));c.jsonld=$('script[type="application/ld+json"]').toArray().map(e=>$(e).text().slice(0,4500));c.iframe=$('iframe[src]').toArray().map(e=>$(e).attr('src'));c.articleLinks=$('article a[href],.article-content a[href],.entry-content a[href]').toArray().map(e=>({href:$(e).attr('href'),text:$(e).text().trim().slice(0,90)})).slice(-20);}o.checks.push(c);}out.push(o);}
fs.writeFileSync(root+'/native-inspection.json',JSON.stringify(out,null,2));console.log(JSON.stringify(out));
NODE
install -o "$SUDO_USER" -m 0600 /var/lib/news-flow/qc-public24-20261123/native-paths.json "$upload_dir/.qc-public24-native.json"
install -o "$SUDO_USER" -m 0600 /var/lib/news-flow/qc-public24-20261123/native-inspection.json "$upload_dir/.qc-public24-inspection.json"
